<!doctype html><html><head><meta charset="utf-8"><title>Cart</title></head><body><h1>Cart</h1><?php if(!$data['items']): ?><p>Cart is empty.</p><?php else: ?><table border="1" cellpadding="8"><tr><th>Product</th><th>Qty</th><th>Total</th></tr><?php foreach($data['items'] as $i): ?><tr><td><?=e($i['product']['name'])?></td><td><?=e($i['qty'])?></td><td><?=e($i['line_total'])?></td></tr><?php endforeach; ?></table><p>Subtotal: <b><?=e($data['subtotal'])?></b></p><?php endif; ?><a href="/products">Products</a></body></html>
